"""policy_review.md generator. Numbers come from facts.compute()/gaps.json, citations from policy.verify_citations()
(both verified against the quest data on every build), prose is hand-written below."""
import collections

import cmdtable as ct
import policy
import scope


def cl(cites, key, n=None):
    items = cites.get(key, [])
    items = items[:n] if n else items
    return ', '.join(f'`{e}:{ln}` {needle}' for e, ln, needle in items)


def table(rows, head):
    out = ['| ' + ' | '.join(head) + ' |', '|' + '---|' * len(head)]
    out += ['| ' + ' | '.join(str(c) for c in r) + ' |' for r in rows]
    return out


def build(data, g, f, patch, inv):
    cites, _ = policy.verify_citations(data)
    after = policy.apply_patch(data.rules, patch)
    pay = f['payments']
    L = []
    A = L.append
    A('# Policy review: Freeside / Strip questline')
    A('')
    A('_Generated by `questlines/strip/build.py` (prose in `review.py`; every number is computed and every `script:line` citation is '
      'verified against the quest data on each build and in `run_tests.py`). Companion files: `rules.patch.json`, `gaps.md`, `dialogue.md`._')
    A('')
    A('## 0. Scope and honesty notes')
    A('')
    A(f'- Quests reviewed: {inv["counts"]["core"]} core (the 19 that `docs/quest-policies/side-freeside-strip.md` / rules.json assign), '
      f'{inv["counts"]["extended"]} extended (Gomorrah/Omertas, Tops talent pool, Atomic Wrangler, Weathers family, Thorn support) and '
      f'{inv["counts"]["system"]} system/dialogue/casino quests. Total {inv["counts"]["quests"]} quests, {inv["counts"]["stages"]} stages.')
    A('- The policy bucket "Side: Freeside / Strip" is a catch-all. By objectives and speakers its quests are Camp Forlorn Hope (VMS30/VMS31), '
      'Bitter Springs (VMS36), the Fort / Caesar surgery (VMS32/VMS35), Great Khans (VMS42/VMS45), the Followers (VMS24/VMS47/High Times), '
      'the Kings (VMS29), Lucky 38 (vfreeformlucky38), Omertas (VMS33) and Nellis (VNellisJack). VMS21/VMS21a (Gomorrah, Omertas) are filed under '
      'Boulder City in rules.json and are reviewed here because their gameplay is the Omertas casino.')
    A('- Rules that take effect today (synccore/src/rules.cpp): Barrier, PartyTether (only gates a stage when `cells` is non-empty), '
      'SetPlayerControls (scope all, lock tracked per cause quest), SaveSuppress, RewardAll, QuestItemDup, RemoveItemPerOwner, ShareKarmaRep, '
      'CompanionOwner, SlideshowEnd, PartyAwareCond (reduction helper), ExcludeFromGate, FastTravelLock, InitiatorDialogue (drops result effects of '
      'non-initiators), PartyWarp (expands a player MoveRef). **PerPlayerScene has no code path** (it is only in the `handled` set).')
    A('- Dialogue result txns are attributed to the quest that OWNS the INFO (`coop_runtime.cpp:181`, `nvcoop_infoquest.json`), i.e. the dialogue '
      'container (VFreeformFreeside, vDialogueGomorrah, ...), not the quest the INFO advances. Rules therefore have to sit on the containers too.')
    A('- Default routing without a rule (`policy.cpp normalizeTxn`): quest/dialogue-result AddItem, RemoveItem, ModActorValue, SetPerk go to '
      'EVERY player; karma and reputation go to every player; every other cause (NPC/object scripts, intents) resolves to the origin player only.')
    A('')
    A('## 1. Owner decisions applied to this questline')
    A('')
    L.extend(table([
        ['Karma / faction rep shared', 'ShareKarmaRep on every quest that awards karma/rep (VMS30, VMS36, VMS25, VMS42, vfreeformlucky38, containers VFreeformFreeside, vDialogueGomorrah, ...)', 'ok, containers added'],
        ['Faction membership shared', 'Omerta / OmertaTraitors / VVault21Private / FollowerFaction joins are `AddToFaction`/`SetFactionRank` on the player', 'rule ok, **capture + apply missing** (gaps.md)'],
        ['Quest items duplicated', 'QuestItemDup present on all item-carrying quests', 'ok'],
        ['Caps/XP rewards: everyone gets the full reward', 'RewardAll; default routing already does this for quest/dialogue causes', 'ok for rewards; **wrong for payments** (F1)'],
        ['Dialogue: initiator chooses', 'InitiatorDialogue on every quest with dialogue; containers added', 'ok; message-box and forced-dialogue cases break it (F3, F7)'],
        ['Free roam, story moments need the party in one area', 'PartyTether / PartyWarp only where a scene moves or locks everybody; per-player scenes use PerPlayerScene', 'tether cells missing (F9)'],
        ['Companions owned by recruiter (open)', 'CompanionOwner on VMS41, VMS35, VDialogueArcadeGannon, vDialogueLily', 'capture missing (F7)'],
    ], ['decision', 'how it applies here', 'status']))
    A('')
    A('## 2. Findings')
    A('')
    A('### F1. Payments in dialogue charge and serve every player (blocker class)')
    A(f'{pay["total"]} INFO result scripts in scope pay caps or chips with `player.RemoveItem` (by owning container: ' +
      ', '.join(f'{k} {v}' for k, v in list(pay['by_container'].items())[:8]) + '). A DialogueResult is a "quest reward cause", so `RemoveItem` '
      'resolves to ALL players: one player buying chips, treatment, a room or a bet is charged on every machine, and the matching `AddItem` / '
      '`AddPerk` resolves to ALL as well. Examples: ' + cl(cites, 'pay30') + '; ' + cl(cites, 'pay38') + '; ' + cl(cites, 'pay_street') +
      '. The chip cashier is the worst case: ' + cl(cites, 'cashier') + ' (the removal count is read from the host inventory); the clinic sells perks: ' +
      cl(cites, 'clinic') + ' (`AddPerk` is captured as `SetPerk`, but a DialogueResult `SetPerk` resolves to ALL players like the item effects).')
    A('')
    A('Proposed: `RemoveItemPerOwner` on every quest/container that owns such INFOs (patch: VMS30, VMS38, VMS42, VMS21a, VFreeformTheStreet01 + new '
      'VFreeformFreeside, vDialogueGomorrah, vDialogueGomorrahGeneric, vDialogueMedicalClinic, vDialogueCasinoCashier, VMSTopsTalentPool, vDialogueTheStrip). '
      'That fixes the charge. The serve side needs **engine change E2** (purchase atomicity), because no rule can send an `AddItem` to the origin today.')
    A('')
    A('### F2. Guest-activated story objects do nothing (blocker class)')
    A(f'{len(f["activate_scripts"])} object/NPC scripts in scope (Lucky 38 elevators, Fort Caesar / Fort Lucius, AutoDoc, Pacer, Gomorrah and Tops doors, '
      f'frisk triggers, casino tables, vendors, ...) mutate shared state from `OnActivate` ({len(f["trigger_scripts"])} more do so from `OnTriggerEnter`). Per L5 rounds 2 and 4, '
      'object scripts also run on a guest but commands such as SetStage, objective changes, AddItem/RemoveItem, MoveTo and quest-var writes are '
      'dropped while a script runs and no host txn is being applied. L10 round 8 (docs/protocol.md section 12) forwards a guest ActivateRef as an intent and the host '
      're-runs the interaction in a capture scope with origin = the guest. Open item that matters here: the stand-in actor is the HOST player until the acting-player '
      'resolution (L5 choke point) and the ghost refID (L6) exist, so every `player.<cmd>` inside those scripts still acts on the host: the Lucky 38 elevator '
      'moves the host (' + cl(cites, 'elevator', 1) + '), the AutoDoc takes the host\'s surgical tools (' + cl(cites, 'autodoc', 1) + '), a frisk strips the host. '
      'Pickups and `TriggerEnter` forwarding (the ' + str(len(f["trigger_scripts"])) + ' trigger scripts) are not done. Not exercised in game. Needs **E4**.')
    A('')
    A('### F3. Message-box choices cannot be made by a guest (blocker class)')
    A(f'{len(f["button_scripts"])} scripts read `GetButtonPressed` in GameMode after a `ShowMessage` box: ' +
      ', '.join(f'`{b["script"]}:{b["line"]}`' for b in f['button_scripts']) + '. They carry irreversible choices: the AutoDoc heals or kills Caesar '
      '(VMS35, ' + cl(cites, 'autodoc', 3) + '), the Fort Howitzer repair that completes VMS32 (' + cl(cites, 'howitzer') + '), Microcline Rock (VMS42 explosives), the injured NCR troopers (VMS30), '
      'Lucky 38 elevator floors; Colonel Moore, Fort Lucius and Fort Caesar use the same pattern for the NCR / Legion endgame confirmation (other lanes). The box and the button live on the host machine only, which breaks "initiator '
      'chooses" for every activator that is not the host: with the forwarded activation the box opens on the HOST screen. The coordinator decision in protocol section 12 '
      'covers only the Fort -> Dam transitions (barrier + PartyWarp); the other boxes have no decision. Needs **E5**.')
    A('')
    A('### F4. Doctor treatment cutscenes: lock the patient, not the party')
    A('Julie Farkas, Alex Richards, Lt Markland (and Dr Usanagi: ' + cl(cites, 'usanagi') + ') share one treatment template: `SetRestrained`/`disablePlayerControls`, an 8-10 s timer, '
      'fade, `ResetHealth`/`RestoreAV`; Julie then restarts the conversation, Alex and Markland step the shared `VDoctors` quest (' + cl(cites, 'julie', 3) + '; ' + cl(cites, 'alex') + '; ' +
      cl(cites, 'markland') + '). The derived rules gave VMS24, VMS47, VFSHighTimes, VMS31 and VMS36 `SetPlayerControls scope=all` plus an inert `PartyTether`; '
      'that would freeze the whole party for every treatment. The scene is per patient: patch removes both and adds `PerPlayerScene` (default control routing is '
      'already "origin"). Open problems: the script runs on the host with origin=host (**E3**), `ResetHealth` / `RestoreAV` / `StartConversation` are not captured '
      '(**E6**), and `VDoctors` (Systems and misc lane) is one shared quest stepped by all doctors.')
    A('')
    A('### F5. Elevators and doors: one rider, not the party')
    A(f'{len([t for t in f["teleports"] if t["fn"] == "moveto"])} `player.MoveTo` statements remain after dropping NPC moves; {f["lucky38_moves"]} are the Lucky 38 elevator/penthouse '
      'doors (' + cl(cites, 'elevator', 1) + '). The derived rule `PartyWarp` on vfreeformlucky38 would drag all players to the basement whenever one '
      'player presses a button, contradicting free roam; patch swaps it for `PerPlayerScene`. VMS29 and VMS32 inherit `PartyWarp` from other lanes\' scripts '
      '(F9). The VMS42 cave explosion keeps `PartyWarp`; the NCR/Legion endgame teleports (Oliver, VHDLegateStartMarker) belong to the endgame lanes and only reach this questline through shared NPC scripts.')
    A('')
    A('### F6. Casino systems: engine-local games, per-player state in shared variables')
    A('Blackjack, roulette and slot tables call `ShowBlackjackMenuParams` / `ShowRouletteMenuParams` / `ShowSlotMachineMenuParams <CasinoData> ...` and '
      'the engine holds the winnings per CasinoData form (engine state, not an Effect; not observed in game). The comps quests poll `GetCasinoWinningsLevel` in GameMode (' + cl(cites, 'vc') + ') and set shared quest '
      'variables (`Banned`, `SmallFry`, `BigWinner`, `Whale`); the tables test `vCasinoComps*.Banned`. So (a) with forwarded activation the menu opens on the HOST screen and the host player stands in for the gambler (F2), (b) winnings and chip/caps changes never reach the host script, (c) the first player to cross a threshold '
      'bans or comps everyone. Frisking is the same: `TopsFriskingTriggerScript` removes the HOST player\'s weapons (' + cl(cites, 'frisk', 1) + '), '
      'Gomorrah keeps `iInGomorrah/bGunsAllowed/iWeaponAlert` in shared quest vars (' + cl(cites, 'gom_door', 1) + '), and companions are found through '
      '`VNPCFollowers.b*Hired` flags (F7). Decision proposed: winnings, bans, frisk state and chip balances are per player; the party stays one Courier for '
      'karma/reputation. That needs the new kind `PerPlayerVars` (rules.patch.json `proposals.kinds`), listed vars verified against the quest scripts.')
    A('')
    A('### F7. Companions')
    A(f'{f["companion_stmts"]} companion statements are in scope. Lily (VMS41) and Arcade (VDialogueArcadeGannon) are recruited by dialogue: '
      '`SetPlayerTeammate 1` + `AddPerk CompanionSuite` + `player.AddPerk StealthGirl` run once on the host (`' + cl(cites, 'lily') + '`); `SetPlayerTeammate` is not captured, the '
      'NPC-subject perk is not tracked, and the player perk is captured as `SetPerk` but resolves to ALL players (dialogue cause). '
      'Casino frisk and Gomorrah entry scripts take the companions from `VNPCFollowers.bBooneHired/bCassHired/...`, a host-only roster. Rules: `CompanionOwner` '
      '(owner = recruiter) on VMS41 (present), VMS35, VDialogueArcadeGannon, vDialogueLily and the two Lily timers (patch). The owner decision stays open.')
    A('')
    A('### F8. Shared faction membership and hostility with no capture')
    A('Omerta membership (`player.addtofaction OmertaFaction`, ' + cl(cites, 'gom_door', 3) + '), `OmertaTraitors` rank changes in every VMS21a ending, '
      '`VVault21Private`, Jacobstown enemy flags (VMS41), `SetPCEnemyOfFaction VCaesarsLegionFaction` (vCCEyeforaneye) and the Great Khans enemy flag '
      '(VRRCPapaKhanSCRIPT:7-8, VMS42/VMS45) change faction state that the owner decision shares. Membership is now captured (`SetFactionRank`, engine_hooks.cpp) and '
      'applied by console on the same actor on every machine (not exercised in game). Still uncaptured: `SetPCEnemyOfFaction`, `ClearFactionPlayerEnemyFlag`, '
      '`RemoveFromAllFactions` (18 NPC uses) and `SendAssaultAlarm` (**E6**), i.e. the hostility half.')
    A('')
    A('### F9. Rules hygiene')
    A(f'- Inert tethers: {", ".join(f["inert_tethers"])} carry `PartyTether` with `cells: []`; the engine proceeds immediately, so the rule claims coverage it does not give. '
      'No cell is referenced by those quests, so none can be proposed from data. Candidates that DO appear in scripts: ' +
      ', '.join(f'`{c}`' for c in ['TopsCasino', 'Gomorrah01', 'Gomorrah03', 'ULCasino', 'ULGourmand', 'ULRooms', 'FreesideSilverRush']) + ' (resolvable) and ' +
      ', '.join(f'`{c}`' for c in patch['blocked_params']['cells']) + ' (not in forms.json.gz).')
    A(f'- Unresolvable params: {len(f["unresolved_rule_params"])} PartyWarp marker names already in rules.json (VMS29, VMS32, VMS42, vfreeformlucky38) are not in '
      'forms.json.gz, so the resolver cannot map them (**E7**). This patch never emits an unresolved EditorID.')
    A('- Shared-NPC noise (endgame confirmations): `' + cl(cites, 'moore_noise') + '` is the NCR endgame confirmation on Colonel Moore (a GameMode message box that saves, '
      'moves the player to General Oliver and locks controls); `' + cl(cites, 'fort_endgame') + '` is the same pattern for the Legion endgame on Fort Lucius / Fort Caesar '
      '(`VHDBattleController.iBattleState` 2, teleport to the Legate camp). VMS29 and VMS45 only send the player to talk to Moore, VMS32 and VMS35 only reach Lucius and '
      'Caesar as quest NPCs. The derived `PartyWarp`, `SaveSuppress`, `SetPlayerControls` and `FastTravelLock` on those quests come from these scripts, not from the quests: '
      'patch removes them from VMS29 and VMS32 (VMS29 keeps a maskless `SetPlayerControls`), and VMS35/VMS45 get only dialogue, companion and condition rules. The endgame '
      'scenes belong to the NCR/Legion lanes.')
    A('')
    A('### F10. Kills, hostility and quest-failing actions')
    A('Kills are shared (union) by policy, so any player\'s kill counts for everybody. Quest-relevant kill/hostility statements per quest: ' +
      (', '.join(f'{q} {n}' for q, n in list(f['kills_by_quest'].items())[:10]) or 'none') + '. Notable: assassinating Pacer / the King / Crocker (VMS29, killing '
      'Crocker fails the quest for the whole party), Papa Khan (VMS45 stage 40), Caesar (VMS35 AutoDoc, ' + cl(cites, 'autodoc', 2) + '), the Omerta thugs (VMS33 stage 30) and Phebus '
      '(VMS25, `IsKiller Player` reduces to any party member). No rule change: shared kills match the owner decision, but the first killer decides the branch for all, so '
      'the dialogue Initiator rule is the only guard rail today (the tethers are inert, F9).')
    A('')
    A('### F11. Player-filtered event blocks')
    A('Event blocks declared for the player actor only fire for the HOST player: ' + ', '.join(f'`{k}` x{v}' for k, v in f['player_blocks'].items()) + '. In this questline they carry quest consequences: '
      + cl(cites, 'pacer_death') + ' (killing Pacer without Van Graff armor turns the Kings against the player), ' + cl(cites, 'janet_death') + ' (Janet, VNellisJack, `iKilledByPlayer`), ' + cl(cites, 'weathers_death') + ' (vCCLeftMyHeart), ' + cl(cites, 'trooper_death') + ' (fails VMS30/VMS31), ' + cl(cites, 'julie_death') +
      ' (Followers turn hostile, reputation penalties). A guest ghost is not the `player` reference, so a guest\'s '
      'hit or kill is invisible to these blocks. Needs **E8**; rules cannot express it (PartyAwareCond reduces functions such as `IsKiller`, not block headers).')
    A('')
    A('### F12. Timers, saves, time-skip')
    A(f'`GameDaysPassed` appears {f["timers"].get("gamedayspassed", 0)} times and `GameHour` {f["timers"].get("gamehour", 0)} (heaviest scripts: ' + ', '.join(f'`{k}` {v}' for k, v in f['timer_scripts'].items()) + '; room rental sets a shared quest variable, '
      '`Set VFreeformTheStreet01.OuttaTime to GameDaysPassed + 1`). Globals are host-wins and shared so waits stay consistent, but anything that advances game time '
      'does it for the whole party. Save triggers: ' + ', '.join(f'`{s["script"]}:{s["line"]}` {s["fn"]}' for s in f['saves']) + ' - all six sit in the NCR/Legion endgame scripts (Moore, Lucius, Caesar) that this '
      'questline reaches through shared NPCs, none in its own stage scripts; the endgame lanes own `SaveSuppress`, and the engine still has no hook that blocks the save (**E6**).')
    A('')
    A('## 3. Barriers, tethers, cinematic control, reward routing')
    A('')
    A('- **Barriers**: none proposed. No stage in this questline requires every player to pass a point; shared progress (three Lucky 38 consoles, Caesar\'s surgery, '
      'the Kings\' showdown) is satisfied by any one player acting. The VMS35 surgery (stages 105-130) is the one stage where a tether would pay off, but no Fort cell is in '
      'forms.json.gz or named by this quest\'s scripts (**E7**).')
    A('- **Tethers**: six inert tethers (F9). Proposal: keep them out of the patch until real cells exist; per-patient treatments and elevators use '
      '`PerPlayerScene` instead.')
    A('- **Cinematic control**: once the endgame noise is removed no scene in this questline needs a party-wide control lock. Treatments (Julie, Alex Richards, Markland, '
      'Usanagi), the VMS35 AutoDoc, elevators, doors and frisking lock only the player they happen to (default routing is the origin). The VMS42 cave explosion is the one '
      'party-wide scene and keeps `PartyWarp`. For any party-wide scene the rule is: initiator drives the dialogue, the host releases, 120 s failsafe.')
    A('- **Reward routing**: rewards (caps/items/XP/karma/rep) go to everyone (`RewardAll`, `ShareKarmaRep`); payments, purchases, bets and hand-ins go to the '
      'payer (`RemoveItemPerOwner` + E2). The same INFO can be a reward in one branch and a payment in another, which is why E2 keys on the txn, not the quest.')
    A('')
    A('## 4. Per-quest table (core and extended)')
    A('')
    rows = []
    for q in inv['quests']:
        if q['group'] == 'system':
            continue
        e = q['edid']
        before = [r['kind'] for r in data.rules['quests'].get(e, {}).get('rules', [])]
        aft = [r['kind'] for r in after['quests'].get(e, {}).get('rules', [])]
        d_add = [k for k in aft if k not in before]
        d_rm = [k for k in before if k not in aft]
        what = (q['objectives'][0]['text'] if q['objectives'] else q['name'] or '')[:62].replace('|', '/')
        note = (patch['amend'].get(e) or patch['new_quests'].get(e) or {}).get('findings', '')
        rows.append([f'`{e}`', (q['name'] or '')[:30].replace('|', '/'), what, q['tier'], len(before) if before else 'none',
                     ('+' + ','.join(d_add) if d_add else '') + (' -' + ','.join(d_rm) if d_rm else '') or 'no change', note or '-'])
    L.extend(table(rows, ['quest', 'name', 'first objective', 'tier', 'rules before', 'patch', 'findings']))
    A('')
    A('System / dialogue / casino quests that gain rules (patch `new_quests`): ' + ', '.join(f'`{e}`' for e in patch['new_quests'] if e not in
      [q['edid'] for q in inv['quests'] if q['group'] != 'system']) + '.')
    A('')
    A('## 5. Proposals that are not rules')
    A('')
    for k in patch['proposals']['kinds']:
        A(f'- **new kind `{k["kind"]}`**: {k["justification"]} Semantics: {k["semantics"]} Interim: {k["interim"]}.')
    for e in patch['proposals']['engine_changes']:
        A(f'- **{e["id"]}** ({e["owner"]}): {e["what"]}')
    A('- **volatile keys**: ' + '; '.join(f'`{q}`: ' + ', '.join(v) for q, v in patch['volatile_keys'].items()) +
      ' are per-transaction scratch variables of the chip cashier; they must never replicate (add to the shared VolatileKeys list, text form `var <form> <name>`).')
    A('')
    A('## 6. Open owner decisions this review needs')
    A('')
    A('1. Casino ledger: per player (recommended) or one shared Courier ledger for winnings, bans, frisk state and chips.')
    A('2. Companion ownership (already open): recruiter-owned is assumed by the patch.')
    A('3. Whether a guest may decide host-affecting story choices made through message boxes (Caesar surgery, Fort Lucius) or whether those are restricted to the host / require a vote.')
    return '\n'.join(L) + '\n'
